package com.rulecraft.decisionops.deployment.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="runtime_environment")
public class RuntimeEnvironment {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID serviceId;@Column(name="environment_key",nullable=false,length=40)private String environmentKey;@Column(nullable=false,length=160)private String name;@Column(name="active_deployment_id")private UUID activeDeploymentId;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long revision;protected RuntimeEnvironment(){}public RuntimeEnvironment(UUID tenantId,UUID projectId,UUID serviceId,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.serviceId=serviceId;environmentKey="SANDBOX";name="Local sandbox";createdAt=updatedAt=now;}public void activate(UUID deploymentId,Instant now){activeDeploymentId=deploymentId;updatedAt=now;}public void clear(Instant now){activeDeploymentId=null;updatedAt=now;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getProjectId(){return projectId;}public UUID getServiceId(){return serviceId;}public UUID getActiveDeploymentId(){return activeDeploymentId;}public String getEnvironmentKey(){return environmentKey;}public String getName(){return name;}public long getRevision(){return revision;}public Instant getUpdatedAt(){return updatedAt;}}
